# numbers_refine.jl: the macros of E112 (results/e112_refine_structured.json, HPG run), Algorithm 1 with certified
# refinement on the perturbed squads formation, written to preamble/numbers_refine.tex. Not registered with
# gen_numbers.jl; main.tex inputs the generated file with \InputIfFileExists.
#
# Macro names: \cnRef<size><omega><eps><quantity>, size A = 256, B = 1024, C = 4096 vehicles requested; omega Lo =
# 0.05, Mid = 0.2, Hi = 1; eps Loose = 0.05, Med = 0.01, Tight = 1e-3, Fine = 1e-4; the fixed coarse teams use Fix.
#
#   julia --project=env scripts/resolution/numbers_refine.jl

using JSON, Printf

function sci(x; d = 1)
    x == 0 && return "0"
    e = floor(Int, log10(abs(x))); m = x / 10.0^e
    s = @sprintf("%.*f", d, m)
    if parse(Float64, s) >= 10; m /= 10; e += 1; s = @sprintf("%.*f", d, m); end
    return "\\ensuremath{$(s)\\times10^{$(e)}}"
end
sig(x; n = 2) = (s = @sprintf("%.*g", n, x); occursin("e", s) ? sci(x) : s)
int(x) = string(round(Int, x))
pct(x) = sig(100x)             # a ratio minus one, in percent
ms(x) = string(round(Int, x))

const SIZES = [(256, "A"), (1024, "B"), (4096, "C")]
const OMS = [("0.05", "Lo"), ("0.2", "Mid"), ("1.0", "Hi")]
const EPSS = [("ref_0.05", "Loose"), ("ref_0.01", "Med"), ("ref_0.001", "Tight"), ("ref_0.0001", "Fine"), ("fix", "Fix")]

function write_refine_numbers(root = normpath(joinpath(@__DIR__, "..", "..")))
    src = joinpath(root, "results", "e112_refine_structured.json")
    E = JSON.parsefile(src); R = E["rows"]; I = E["instances"]
    lines = String["% GENERATED by scripts/resolution/numbers_refine.jl from results/e112_refine_structured.json; do not edit by hand.",
                   "% Regenerate with `julia --project=env scripts/resolution/numbers_refine.jl`.",
                   "% E112 ran on $(join(E["hosts"], ", ")) (jobs $(join(E["jobs"], ", ")), commit $(join(E["commits"], ", "))).", ""]
    put(name, val, meaning) = (push!(lines, "% $meaning"); push!(lines, "\\newcommand{\\$name}{$val}"))
    med(r, f) = r[f]["median"]; mx(r, f) = r[f]["max"]; mn(r, f) = r[f]["min"]
    put("cnRefPeriodMs", int(E["period_ms"]), "sampling period h in ms")
    put("cnRefDeltaRel", sci(E["delta_rel"]), "delta over the value of the coarse teams at x(0)")
    viol = Dict("cert_viol_total" => 0, "tail_viol_total" => 0, "value_viol_total" => 0); runs = 0
    for (n, S) in SIZES, (om, O) in OMS
        ik = "n$(n)_om$(om)"
        haskey(I, ik) || continue
        ii = I[ik]
        pre = "cnRef$S$O"
        put(pre * "Seeds", int(length(ii["runs"])), "$ik: seeds")
        put(pre * "N", int(ii["n"]["median"]), "$ik: vehicles (median over seeds)")
        put(pre * "Coarse", int(ii["teams_phi0"]["median"]), "$ik: coarsest lossless teams of the unperturbed weights, the start (median)")
        put(pre * "Lossless", int(ii["teams_lossless_perturbed"]["median"]), "$ik: coarsest lossless teams of the perturbed weights (median)")
        ex = R["$(ik)_exact"]; put(pre * "ExactMs", ms(med(ex, "ms_med")), "$ik: centralized MPC, Clarabel 1e-9, median ms per sample")
        if haskey(R, "$(ik)_coord")
            co = R["$(ik)_coord"]
            put(pre * "CoordMs", ms(med(co, "ms_med")), "$ik: centralized MPC, TeamMPC default accuracy, median ms per sample")
            put(pre * "CoordMsMax", ms(mx(co, "ms_max")), "$ik: centralized MPC, TeamMPC, worst ms per sample")
        end
        for (arm, A) in EPSS
            key = "$(ik)_$arm"; haskey(R, key) || continue
            r = R[key]; p = pre * A
            for f in keys(viol)
                haskey(r, f) && (viol[f] += r[f])
            end
            runs += r["seeds"]
            put(p * "Cost", pct(med(r, "cost_ratio") - 1), "$key: closed-loop cost over that of centralized MPC, minus 1, percent (median)")
            put(p * "CostMax", pct(mx(r, "cost_ratio") - 1), "$key: same, worst seed")
            put(p * "Ms", ms(med(r, "ms_med")), "$key: median ms per sample t >= 1 (solve + certificate + splitting)")
            put(p * "MsMax", ms(mx(r, "ms_max")), "$key: worst ms per sample t >= 1 over seeds")
            put(p * "Met", int(100 * med(r, "met_frac")), "$key: fraction of samples t >= 1 within the period, percent (median over seeds)")
            put(p * "MetMin", int(100 * mn(r, "met_frac")), "$key: fraction of samples t >= 1 within the period, percent (worst seed)")
            put(p * "SolveMs", ms(med(r, "solve_ms_med")), "$key: median team solve ms")
            put(p * "CertMs", ms(med(r, "cert_ms_med")), "$key: median certificate ms")
            put(p * "GapMed", sci(med(r, "gap_rel_med")), "$key: true gap over J*, median over samples, median over seeds")
            put(p * "GapMax", sci(mx(r, "gap_rel_max")), "$key: true gap over J*, worst sample")
            put(p * "EtaGap", sig(med(r, "eta_over_gap_med"); n = 3), "$key: certificate over true gap, median")
            put(p * "EtaGapMin", sig(mn(r, "eta_over_gap_min"); n = 3), "$key: certificate over true gap, smallest")
            if arm != "fix"
                put(p * "Teams", int(med(r, "teams_final")), "$key: teams at the last sample (median)")
                put(p * "TeamsMax", int(mx(r, "teams_final")), "$key: teams at the last sample (largest)")
                put(p * "TeamsZero", int(med(r, "teams_after0")), "$key: teams after the splits of sample 0 (median)")
                put(p * "SplitsLater", int(mx(r, "splits_after0")), "$key: splits after sample 0, largest over seeds")
                put(p * "SplitSamples", int(mx(r, "samples_split_after0")), "$key: samples t >= 1 with a split, largest over seeds")
                put(p * "ZeroMs", ms(med(r, "t_total0") * 1e3), "$key: sample 0 time in ms (solve, certificate and the splits), median")
                haskey(r, "split_ms_med") && put(p * "SplitMs", ms(med(r, "split_ms_med")), "$key: median splitting ms on samples t >= 1 with a split")
            end
        end
    end
    rat = [p[2] / p[1] for v in values(E["scatter"]) for p in v if p[1] > 1e-7]
    put("cnRefEtaGapMinAll", sig(minimum(rat); n = 3), "certificate over true gap, smallest over every sample of every team arm (gap > 1e-7 J*)")
    put("cnRefEtaGapMaxAll", sig(maximum(rat); n = 3), "certificate over true gap, largest over the same samples")
    srt = sort(rat); q(a) = srt[clamp(ceil(Int, a * length(srt)), 1, length(srt))]
    put("cnRefEtaGapMedAll", sig(q(0.5); n = 3), "certificate over true gap, median over the same samples")
    put("cnRefEtaGapPnnAll", sig(q(0.99); n = 3), "certificate over true gap, 99th percentile over the same samples")
    put("cnRefSamples", int(sum(length(v) for v in values(E["scatter"]))), "certified samples checked (all team arms)")
    put("cnRefRuns", int(runs), "closed loops checked (sizes x omega x arms x seeds, team arms only)")
    put("cnRefCertViol", int(viol["cert_viol_total"]), "samples with gap > eta, all team arms (must be 0)")
    put("cnRefTailViol", int(viol["tail_viol_total"]), "samples violating sum_{s>=t} l(s) <= W_t, all team arms (must be 0)")
    put("cnRefValueViol", int(viol["value_viol_total"]), "samples violating W_t <= (J*_t + delta)/(1 - eps), refinement arms (must be 0)")
    out = joinpath(root, "preamble", "numbers_refine.tex")
    write(out, join(lines, "\n") * "\n"); println("wrote ", out)
end

if abspath(PROGRAM_FILE) == @__FILE__
    write_refine_numbers()
end
